    return out


java
class Solution {
  public int[] stampGatesProofStrip(int[] readings) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {for(int x:a)out.add(Math.max(0,x));}
    return out.stream().mapToInt(Integer::intValue).toArray();
  }
}
